-- D-16 Environmental Monitoring, still DRAFT (tasks 16.6 and 16.9):
--   FRM-706  Environmental Monitoring Results Log  - new, draft
--   FSQM-015 Environmental Monitoring Program      - draft, amended
--
-- 1. The results log FSQM-015 could not name now exists, so the program names it (Part 8, the form
--    references and the records). FRM-706 is the next free number in the 700 block.
-- 2. Sample points are listed under each zone in Part 3 (18 points). They are a first list for the SQF
--    Practitioner to correct on the floor. How many are sampled and how often waits for a laboratory.
-- 3. The yearly ambient air test (11.7.1.2) is taken out. FSQM-013, issued, records 11.7.1.1 to 11.7.1.5
--    as not engaged because the site processes no high-risk food; the draft said the opposite of an
--    issued document. Owner's decision 2026-10-07: follow FSQM-013, and look again when the water
--    activity of the finished product is measured.
--
-- Both documents stay draft. Nothing is issued here; no laboratory is engaged and no sample is taken.
-- FSQM-015's content is changed in ONE UPDATE.

begin;

do $guard$
declare d record;
begin
  if exists (select 1 from public.sop_documents where sop_number = 'FRM-706') then
    raise exception 'FRM-706 is already in use.';
  end if;
  select status, revision, md5((content->'procedure')::text) as pmd5 into d
    from public.sop_documents where sop_number = 'FSQM-015';
  if d.status is distinct from 'draft' or d.revision is distinct from 'New' then
    raise exception 'FSQM-015 is not the draft this migration expects.';
  end if;
  if d.pmd5 <> '24b1bf06bf1dcda58dc558ae6593dc55' then
    raise exception 'FSQM-015 procedure has changed since this migration was written (%).', d.pmd5;
  end if;
  if (select count(distinct sop_number) from public.sop_documents
       where sop_number in ('FSQM-013', 'FSQM-039', 'FRM-206', 'FRM-007', 'FRM-702') and status = 'active') <> 5 then
    raise exception 'a document this migration names is missing or not issued.';
  end if;
  if not exists (select 1 from public.sop_documents d2, jsonb_array_elements_text(d2.content->'procedure') l
                  where d2.sop_number = 'FSQM-013' and d2.status = 'active' and l like '%11.7.1.1 to 11.7.1.5%'
                    and l like '%no high-risk food%') then
    raise exception 'FSQM-013 no longer records 11.7.1 as not engaged.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FRM-706', 'Environmental Monitoring Results Log', 'form', 'Module 2', 'draft', 'New',
   '2.4.8.2, 2.4.8.3', true, jsonb_build_object('form_schema', $q${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{reason} - {date}"}, "sections": [{"id": "round", "title": "1. The sampling round", "fields": [{"id": "how_this_works", "type": "info", "label": "How to use this", "text": "One record for each sampling round (FSQM-015). Fill sections 1 and 2 on the day the samples are taken and save a draft. When the laboratory report comes back, enter each result, attach the report, complete section 3 and submit. Do not clean a sample point specially because it is about to be swabbed."}, {"id": "reason", "type": "select", "label": "Reason", "width": "third", "required": true, "showInList": true, "options": ["Routine round", "Re-test after an unsatisfactory result", "Vector swabs around an unsatisfactory result", "After a change to the floor, the process or the clean"]}, {"id": "date", "type": "date", "label": "Date sampled", "width": "third", "required": true, "showInList": true}, {"id": "rotation_day", "type": "select", "label": "Day of the rotation", "width": "third", "required": true, "options": ["Day 1 - bake", "Day 2 - dip and seal", "Day 3 - package", "No production"]}, {"id": "laboratory", "type": "text", "label": "Laboratory", "width": "third", "required": true, "help": "As listed on FRM-206"}, {"id": "date_sent", "type": "date", "label": "Date sent", "width": "third", "required": true}, {"id": "report_ref", "type": "text", "label": "Laboratory report no.", "width": "third", "required": true}, {"id": "date_reported", "type": "date", "label": "Date reported", "width": "third", "required": true}]}, {"id": "samples", "title": "2. Samples", "fields": [{"id": "samples", "type": "grid", "label": "Samples taken", "required": true, "rowDialog": true, "help": "One line for each swab and each organism asked for.", "columns": [{"id": "point", "label": "Sample point", "type": "select", "required": true, "width": 2, "options": ["1-A Depanning table top", "1-B Dunk sink, inside", "1-C Perforated dunking tray", "1-D Baking tray the dunked product is placed on", "2-A Cooling rack shelf, where the pans sit", "2-B Cooling rack cover, inside", "2-C Cooling rack upright and castor", "2-D Dunk sink, outside and stand", "2-E Vacuum sealer, bed, seal bar, lid and control panel", "2-F Kettle, outside and tilt handle", "3-A Floor under the cooling racks", "3-B Floor at the dunk sink (in use)", "3-C Floor drain nearest the dunk sink (in use)", "3-D Hand-wash sink, taps and basin", "3-E Mop sink and cleaning tools", "3-F Waste bin, lid and rim (in use)", "4-A Warehouse floor at the door from production", "4-B Break area table", "Other - say where in Notes"]}, {"id": "state", "label": "When", "type": "select", "required": true, "width": 1.3, "options": ["After cleaning, before production", "In use"]}, {"id": "time", "label": "Time", "type": "text", "width": 0.7}, {"id": "organism", "label": "Tested for", "type": "select", "required": true, "width": 1.2, "options": ["Listeria species", "Enterobacteriaceae", "Other - say which in Notes"]}, {"id": "method", "label": "Method (as on the report)", "type": "text", "width": 1}, {"id": "result", "label": "Result", "type": "select", "required": true, "width": 1.2, "options": ["Not detected", "Within the limit", "ABOVE THE LIMIT", "PRESUMPTIVE POSITIVE", "CONFIRMED POSITIVE"]}, {"id": "count", "label": "Count, if reported", "type": "text", "width": 1}, {"id": "notes", "label": "Notes", "type": "text", "width": 1.5}], "rows": {"mode": "dynamic", "min": 1, "addLabel": "Add sample"}}]}, {"id": "outcome", "title": "3. Result and actions", "fields": [{"id": "overall", "type": "select", "label": "Overall", "width": "half", "required": true, "showInList": true, "options": ["All satisfactory", "One or more unsatisfactory"]}, {"id": "actions", "type": "textarea", "label": "If unsatisfactory: what was done", "help": "The vector swabs, the clean and re-swab, and what was found to be the cause (FSQM-015 Part 7)"}, {"id": "hold_ref", "type": "text", "label": "Hold record (FRM-702), if product was held", "width": "half"}, {"id": "capa_no", "type": "text", "label": "CAPA Report no. (FRM-007)", "width": "half"}]}, {"id": "sign", "title": "4. Sign-off", "fields": [{"id": "sampled_by", "type": "signature", "label": "Sampled by", "role": "filler", "required": true, "statement": "I took these samples at the points and times shown, and no point was cleaned specially beforehand."}, {"id": "reviewed_by", "type": "signature", "label": "Results reviewed by the SQF Practitioner", "role": "verifier", "required": true, "statement": "I have read the laboratory report. The results above are as reported and the actions are as stated."}]}]}$q$::jsonb));

update public.sop_documents
   set content = content || $q${"purpose": "This program states how Adventure Bakery monitors its production environment for pathogens and indicator organisms: who is responsible, where and when samples are taken, which organisms are tested for and why, what is done when a result is unsatisfactory, and how results are trended. It exists because product is open to the room after the oven, which is the site's only kill step, and environmental monitoring is the only control that looks for contamination in the room rather than in the product. It addresses the Environmental Monitoring element of the SQF Food Safety Code: Food Manufacturing, Edition 9 (2.4.8).", "procedure": ["Product is exposed to the room after the kill step, and that exposure is what this program monitors.", "> The oven is this site's kill step. After it, product cools in its molds on covered racks, is depanned onto a table, is dunked and drained on a perforated tray, and is placed on a baking tray before it goes into its pouch — all of it open to the room. Anything living in that room during that window can reach the product without passing through another lethal step. Nothing downstream of the oven kills; the seal excludes.", "> That is the whole reason this program exists, and it is why the program looks at the room rather than at the product. A pathogen that establishes itself in a drain, a rack or the frame of the sealer reaches a small and shifting fraction of units. Testing finished product for it is a well-documented way to keep finding nothing while the problem continues.", "> SQF 2.4.8.1 asks for a risk-based program covering the manufacturing processes and the immediate surrounding areas that impact them, with the responsibility and the methods documented and implemented. Parts 2 to 8 are that program.", "This program covers the room. It does not test product, and it does not change the position FSQM-014 takes on product analysis.", "• In scope: the production floor of units 415 and 425 on all three days of the rotation, and the surfaces, drains, floors, walls, equipment, cleaning tools and air within it; the packaging materials storage; and the ambient warehouse in which finished product is held.", "• Not in scope: ambient air testing and the other high-risk process clauses (SQF 11.7.1.1 to 11.7.1.5). FSQM-013 records that the site processes no high-risk food, so those clauses are not engaged. HIGH CARE on FSQM-039 is the site's own name for where product is open after the oven; it is not a high-risk area under the Code. This is looked at again when the water activity of the finished product is measured.", "• Not in scope: any analysis of raw material, packaging, work-in-progress or finished product. FSQM-014 Part 2 records that the site inspects and does not analyse, and nothing here disturbs that. An environmental sample is taken from the room, never from the product.", "• Not in scope: the hygiene zoning itself, which is drawn on FSQM-039, and the GMP controls over the areas it divides, which are FSQM-012.", "• Not in scope: the cleaning and sanitation program in the 900 series. This program measures whether that cleaning is working. It does not specify it, and it is not a substitute for the pre-operational inspection recorded on FRM-903.", "> The distinction between an environmental sample and a product sample is not a technicality and is stated here because the two documents must be read together. FSQM-014 Part 2 says plainly that no external laboratory is used. That sentence is about product, and Part 6 below records the amendment it needs once an environmental sample is first sent.", "Samples are classified by how close the surface is to exposed product, in four zones. This is not the same thing as the hygiene areas drawn on FSQM-039.", "• Zone 1 — surfaces that contact exposed product. The table the product is depanned onto, the inside of the dunk sink, the perforated tray it is dunked and drained on, the baking tray it is placed on afterwards, and hands and gloves that handle open product.", "◦ 1-A Depanning table top", "◦ 1-B Dunk sink, inside", "◦ 1-C Perforated dunking tray", "◦ 1-D Baking tray the dunked product is placed on", "• Zone 2 — non-product-contact surfaces close to Zone 1. Cooling rack shelves, covers, uprights and castors, the outside of the dunk sink, equipment frames and control panels, the underside of tables, and the vacuum sealer: the product is already in its pouch when it reaches the sealer, so the sealer touches the pouch and not the product.", "◦ 2-A Cooling rack shelf, where the pans sit", "◦ 2-B Cooling rack cover, inside", "◦ 2-C Cooling rack upright and castor", "◦ 2-D Dunk sink, outside and stand", "◦ 2-E Vacuum sealer, bed, seal bar, lid and control panel", "◦ 2-F Kettle, outside and tilt handle", "• Zone 3 — other surfaces within the production area. Floors, drains, walls, door handles, waste bins, pallet jacks, cleaning tools and their storage, hoses and the mop sink.", "◦ 3-A Floor under the cooling racks", "◦ 3-B Floor at the dunk sink (in use)", "◦ 3-C Floor drain nearest the dunk sink (in use)", "◦ 3-D Hand-wash sink, taps and basin", "◦ 3-E Mop sink and cleaning tools", "◦ 3-F Waste bin, lid and rim (in use)", "• Zone 4 — areas outside the production area. Storage, corridors, welfare and locker areas, the office side, and the routes between them.", "◦ 4-A Warehouse floor at the door from production", "◦ 4-B Break area table", "> The points listed under each zone are the sample points. Each keeps its number, so results from one point can be compared over time. A point is added, moved or removed by revising this Part, never on the day.", "> FSQM-039 divides the floor by hygiene status — NON-PRODUCTION, PACKAGING MATERIALS STORAGE, RAW / PRE-BAKE, BAKE, COOLING and HIGH CARE. Those describe what is allowed to happen in a place. The zones above describe what a positive result found in a place would mean. The two are different questions and they cut across each other, so a sample point is identified by both: 'perforated dunking tray — Zone 1, HIGH CARE'.", "> Naming them both is deliberate. A programme that carried only the hygiene areas could not say why a swab of a floor matters less than a swab of a rack; one that carried only the zones could not say why the same bay is sampled differently from one day of the rotation to the next.", "> THE DUNK BAY IS THE POINT WHERE THE TWO OVERLAP AND MATTER MOST. It holds raw batter on Day 1 and post-bake product on Day 2, and what separates those is the changeover clean and nothing else. Its Zone 1 and Zone 2 points are therefore the most informative surfaces in the building, and the sample plan weights them accordingly.", "The target organisms are Listeria species in the post-lethality area and Enterobacteriaceae as a hygiene indicator, and both are provisional until the finished product's water activity is measured.", "• Listeria species — the pathogen target, sampled in the high-care and cooling areas and in the dunk bay on Day 2. Listeria species rather than Listeria monocytogenes alone: the genus is the harbourage indicator, it is the cheaper and more sensitive screen, and a site that waits for the species to appear has waited too long.", "• Enterobacteriaceae — the hygiene indicator, sampled on food-contact and near-contact surfaces after cleaning. It is inexpensive enough to run often, which is what makes a trend possible at all.", "> WHY LISTERIA. The dip is a wet step, it sits inside the high-care area, and it happens after the only kill step in the process. Standing water and a cooled product surface in one bay is the classic description of where Listeria establishes itself. That combination is present here on Day 2, so the organism is monitored whether or not the finished product turns out to support its growth.", "> WHY NOT SALMONELLA ON THE DRY SIDE. Flour and other dry ingredients are a well-known Salmonella vehicle, and monitoring for it upstream of the oven was considered and rejected. Everything on the raw side passes through the bake, which is the validated kill step, so a positive found there would not implicate product and would not change any control. Spending the testing budget upstream of a kill step buys information the kill step has already answered. If the process ever gains a route by which raw-side material reaches product after the oven — a rework loop, a topping added cold, a shared utensil — this decision is revisited immediately.", "> WHY BOTH TARGETS ARE PROVISIONAL. The HACCP plan calls the product shelf-stable on the grounds of reduced water activity, but that claim is made about the cake as it leaves the oven and the dip comes after it. Dipping in rum, water and sugar syrup adds water back. The figure that actually governs shelf stability is the water activity of the finished, sealed, equilibrated unit, and that figure is not measured and appears nowhere in the document set. Until it does, this program takes the conservative position and monitors as though growth in product were possible. When the measurement exists the target organisms are reviewed against it, and if the finished product cannot support growth the emphasis here properly shifts toward indicator organisms and away from pathogen screening.", "> That measurement is not this program's to make; it belongs to the food safety plan. This Part records the dependency so that the choice made here can be explained rather than merely asserted, which is what 2.4.8.2 (i) asks for when it requires the applicable pathogens or indicator organisms for the industry to be detailed.", "Samples are taken after cleaning and before production, except at points that can only be judged in use.", "> PRE-OPERATIONAL SAMPLING IS A DELIBERATE CHOICE AND IT IS THE PROPORTIONATE ONE HERE. A Zone 1 swab taken during a run places the running batch in question, and there is no laboratory turnaround fast enough to resolve that before the product would otherwise ship. Sampling after the clean and before production means a positive implicates the clean, which is a condition the site can act on, rather than a lot it would have to hold for days waiting on a result.", "> It is not the more lenient choice. A surface that is positive after cleaning is a surface the cleaning did not reach, which is precisely the finding this program is for.", "• Points that can only be meaningfully assessed in use — drains, the floor around the dunk sink, waste handling — are sampled during or immediately after a run, and the sample plan marks them as such.", "• How many of the points in Part 3 are sampled in a round, and how often, is set and written here when the laboratory is engaged, because its price for each sample is what decides it. Until then no sampling is carried out.", "• Swabs are taken by the SQF Practitioner, or by a person the SQF Practitioner has trained and recorded as competent on FRM-952.", "• Each sample records the sample point and its zone, the date and time, whether the area was pre-operational or in use, the organism requested, and who took it.", "• Each swab covers the area the laboratory's method specifies, and the same area at the same point each time, so that results from one point can be compared with each other.", "• Samples are held and transported as the laboratory instructs and are sent the same day they are taken.", "• A sample point shall not be given a clean it would not otherwise have received because it is about to be swabbed.", "> The last rule is the one that decides whether any of the others are worth performing. A point that is specially cleaned before sampling reports on a clean that does not happen in the ordinary course, and the programme then measures its own preparation.", "The analysis is performed by an external laboratory, and the method is settled before the laboratory, and the laboratory before the first sample.", "• The laboratory shall be accredited to ISO/IEC 17025, or to an equivalent international standard, for each method it performs for this site.", "• The laboratory shall be listed on FRM-206 Contract Services Register before the first sample is sent to it, with its accreditation held on that entry.", "• The sample plan shall name, for each organism, the method used, its detection limit, the sample type the method requires, and the reporting time.", "> That order — method, then laboratory, then sample — is FSQM-014 Part 2's rule and it is adopted here unchanged. A sample sent before the method is settled produces a number nobody can interpret and a result nobody can defend.", "> A CONSEQUENTIAL AMENDMENT, RECORDED SO THE TWO DOCUMENTS DO NOT DISAGREE. FSQM-014 Part 2 states that no external laboratory is used and that no analysis is commissioned. Read in context that statement is about raw material, packaging, work-in-progress and finished product, and it remains true of all four. But the first environmental sample sent for analysis makes this site a user of an external laboratory, and a reader of FSQM-014 alone would be misled. FSQM-014 Part 2 is therefore amended to scope its sentence to product analysis, in the same revision that brings this program into force — not afterwards.", "An unsatisfactory result is investigated, and the investigation starts before the confirmation comes back.", "• A presumptive positive is treated as a positive for the purpose of starting work. Confirmation is requested, and the investigation begins without waiting for it.", "• Vector swabbing is carried out around the point — the surfaces, drains and equipment it drains to, sits on, touches or shares a route with — to find where the organism is living rather than merely where it was found.", "• The point is cleaned and sanitised, then re-swabbed, and sampling at that point is intensified until three consecutive negative results are obtained.", "• Where the same organism returns to the same point, the response addresses the cause — standing water, a cracked surface, a hollow frame, a cleaning method that cannot reach — and not the surface alone.", "• A CAPA is raised under FSQM-009 wherever its Part 3 requires one. A confirmed Zone 1 positive for Listeria species in the post-lethality area always raises one.", "• Where a Zone 1 positive is found on a surface that contacted exposed product, the product that contacted it is placed on Hold under FSQM-018 and recorded on FRM-702, and release is refused under FSQM-020 until the disposition is made.", "> This Part is written before the first positive rather than after it, and that is the whole of its value. The pressure at the moment a positive arrives is to explain it away — a bad swab, a one-off, a laboratory error — and a site that has not decided in advance what it will do is deciding it under exactly the conditions that produce the wrong answer.", "> A single positive in Zone 3 is information and not an emergency. The same organism at the same point three times is a resident population, and finding resident populations is what this program is for. Neither statement licenses ignoring the first result.", "> 2.4.8.2 (iv) requires the methods for handling elevated or undesirable results to be described, and this Part is that description.", "Results are trended, and the trend is reviewed by management. A file of results is not compliance with 2.4.8.3.", "• Every sampling round is recorded on FRM-706 Environmental Monitoring Results Log: each sample with its sample point, zone, organism and result, the laboratory and the method, with the laboratory report attached.", "• The SQF Practitioner reviews the results at least monthly and reports them on FRM-009 Monthly SQF Update.", "• The trend over the year is reviewed at the annual management review and recorded on FRM-001.", "• The SQF Practitioner reviews this program at least annually, and before that whenever the floor is re-zoned, the process changes, the finished product's water activity is measured, or the results themselves indicate the plan is looking in the wrong places.", "> What counts as a trend here: repeat positives at one point, a drift upward in indicator counts at any point, a cluster of positives sharing a drain or a route, and — the one most often missed — a listed point that has not actually been sampled.", "> 2.4.8.3 requires results to be monitored, tracked and trended and preventive action to be taken where an unsatisfactory result or trend is seen, referring to 2.5.3.1. That referral is the CAPA program, FSQM-009, which exists and is active, so the preventive-action limb has somewhere to land."], "form_references": "FRM-206 Contract Services Register — where the external laboratory is listed, with its accreditation, before the first sample is sent.\nFRM-007 CAPA Report — where a corrective and preventive action arising from a positive result is raised and closed.\nFRM-702 Non-Conforming Material Hold & Tagging Record — where product implicated by a Zone 1 positive is placed on hold.\nFRM-009 Monthly SQF Update — where the monthly results review is reported.\nFRM-001 Management Review Record — where the annual trend is reviewed.\nFRM-952 Training and Competency Record — where a person trained to take samples is recorded as competent.\nFRM-706 Environmental Monitoring Results Log — where every sampling round and its results are recorded.", "records": "Sample records and laboratory reports — every result, held with its sample point, zone, date, organism, method, laboratory and outcome on FRM-706 Environmental Monitoring Results Log. Laboratory reports are retained as received.\n\nInvestigation and corrective action records — on FRM-007 under FSQM-009.\n\nProduct hold and disposition records — on FRM-702 under FSQM-018.\n\nMonthly review — on FRM-009. Annual trend review — on FRM-001.\n\nRetention follows the record control requirements of SOP-2.2.3. Superseded revisions of this program are retained by the sop_document_history trigger, which snapshots the row whenever a watched field changes on a published document.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 2.4.8 Environmental Monitoring. 2.4.8.1 requires a risk-based program for all food manufacturing processes and the immediate surrounding areas which impact them, with the responsibility and methods documented and implemented. 2.4.8.2 requires a sampling and testing schedule detailing the applicable pathogens or indicator organisms, the number and frequency of samples, the locations and their rotation, and the methods for handling elevated or undesirable results. 2.4.8.3 requires results to be monitored, tracked and trended with preventive action under 2.5.3.1.\n\n11.7.1 High-Risk Processes, including the annual ambient air test of 11.7.1.2, is not part of this program. FSQM-013 records 11.7.1.1 to 11.7.1.5 as not engaged, because the site processes no high-risk food.\n\nWHAT THIS DOCUMENT CLOSES, AND WHAT IT DOES NOT. 2.4.8.1 requires the program to be documented AND implemented. This document is the documented limb. The implemented limb requires an accredited laboratory and a sampling frequency, neither of which exists as this is written — see the open items in the revision history. 2.4.8.2 is framed here: the organisms are in Part 4, the sample points in Part 3 and the handling of unsatisfactory results in Part 7. The number and frequency of samples wait for the laboratory. Recording that plainly is the same choice FSQM-017 made in recording that 2.5.1.1 closes only in part, and FSQM-014 made in stating that the site does not analyse.\n\nFSQM-039 Facility Layout and Product Flow — the hygiene zoning this program's sample points are placed against. Its zone boundaries were confirmed on the floor before it was issued.\nFSQM-013 Module 11 Applicability & Exemption Analysis — where the high-risk process clauses are recorded as not engaged.\nFSQM-012 Good Manufacturing Practices Program — the personnel, premises and processing controls that keep the room in the condition this program samples.\nFSQM-014 Product Sampling, Inspection and Analysis Program — the product-side counterpart to this document, and the source of the method-then-laboratory-then-sample rule adopted in Part 6. Its Part 2 is amended when this program issues; see Part 6.\nFSQM-009 Corrective and Preventive Action (CAPA) Program — where a positive result's corrective and preventive action is raised, which is the 2.5.3.1 referral 2.4.8.3 makes.\nFSQM-018 Non-Conforming Product and Equipment — where product implicated by a Zone 1 positive is held and dispositioned.\nFSQM-020 Product Release Program — the release that is refused while such a hold stands.\nFSQM-017 Validation and Verification Program — the master verification schedule this program's activities join when it issues.", "revision_history": "Rev New — written 2026-09-17; rotation corrected to three days 2026-09-18, following FSQM-039; sample points listed, results log named and the ambient air test removed 2026-10-07. DRAFT. Not approved, not in force.\n\nWHY IT EXISTS. The site had no environmental monitoring program of any kind, and 2.4.8.1 was scored against that absence. The need is not formal: product cools, is dipped and is loaded into the sealer while open to the room, so the room is the last place contamination can enter and the only place it can be looked for before the pack is closed.\n\nWHAT IT DELIBERATELY DOES NOT DO. It does not set how many samples are taken in a round or how often. That waits for a laboratory, because its price for each sample is what decides it.\n\nOPEN BEFORE ISSUE — THREE ITEMS, ALL OF THEM COST OR JUDGEMENT:\n\n1. THE TARGET ORGANISM SET IS PROPOSED, NOT CONFIRMED. Part 4 proposes Listeria species in the post-lethality area and Enterobacteriaceae as the hygiene indicator, with the reasoning for each and for rejecting Salmonella on the dry side. This decides what the program costs to run, so it is Senior Site Management's to confirm and not the author's to assume.\n\n2. NO LABORATORY IS ENGAGED. One must be selected, confirmed accredited to ISO/IEC 17025 or equivalent for the methods used, and listed on FRM-206 Contract Services Register. Its price per sample is also what makes the sample plan's frequency decidable, so this item gates more than itself. It would be this site's second contracted service; pest control is the first.\n\n3. THE SAMPLE POINTS IN PART 3 ARE A FIRST LIST. The SQF Practitioner corrects them on the floor, and the list of points on FRM-706 is changed to match, before this program issues.\n\nDECIDED, AND NOT OPEN:\n\nSampling is pre-operational by default — after the clean, before production — except at points that can only be judged in use. Part 5 gives the reasoning: a positive then implicates the clean, which the site can act on, rather than a lot it would hold for days awaiting a result.\n\nListeria is monitored at the genus level rather than waiting for L. monocytogenes.\n\nThe dry side upstream of the oven is not monitored for pathogens, because everything on it passes through the validated kill step. Part 4 states what would reverse that: any route by which raw-side material reaches product after the oven.\n\nThe high-risk process clauses, 11.7.1.1 to 11.7.1.5, are not engaged (FSQM-013), so the annual ambient air test is not part of this program. This is looked at again when the water activity of the finished product is measured.\n\nSTATED DEPENDENCY, AND NOT A DEFECT:\n\nThe target organisms are provisional until the finished product's water activity is measured on a sealed, equilibrated unit. That measurement belongs to the food safety plan, not to this program. Until it exists this program takes the conservative position and monitors as though growth in product were possible. Part 4 records what changes when the figure arrives.\n\nCONSEQUENTIAL ON ISSUE — ONE ITEM:\n\nFSQM-014 Part 2 states that no external laboratory is used. That is true of product analysis and stays true, but it reads as a statement about the site. It is scoped to product analysis in the same revision that brings this program into force, so that the two documents never disagree in the interval.", "definitions": "Environmental monitoring zone (Zone 1 to Zone 4): a classification of a sample point by its proximity to exposed product. It is a property of the point, not a place on the floor, and it is not the same as the hygiene areas drawn on FSQM-039. See Part 3.\n\nPost-lethality exposure: the period after product leaves the oven during which it is open to the room — cooling, depanning, the dunk and draining, until it is placed in its pouch.\n\nIndicator organism: an organism tested for not because it is itself the hazard, but because finding it shows conditions in which the hazard could survive or grow.\n\nPresumptive positive: a screening result indicating the target organism may be present, reported before confirmatory testing is complete.\n\nVector swabbing: additional samples taken around a positive result to locate the source of the organism rather than the place it was found.\n\nHarbourage: a place in which an organism survives cleaning and establishes a resident population — typically a crack, a hollow frame, a drain or a standing wet area."}$q$::jsonb,
       sqf_reference = '2.4.8.1, .2, .3'
 where sop_number = 'FSQM-015' and status = 'draft';

do $verify$
declare d record; f record;
begin
  select status, revision, approved_by, effective_date, sqf_reference, content into d
    from public.sop_documents where sop_number = 'FSQM-015';
  if d.status <> 'draft' or d.revision <> 'New' or d.approved_by is not null or d.effective_date is not null then
    raise exception 'FSQM-015 status, revision or approval changed.';
  end if;
  if jsonb_array_length(d.content->'procedure') <> 79 then
    raise exception 'FSQM-015 procedure is % lines, expected 79.', jsonb_array_length(d.content->'procedure');
  end if;
  if d.content::text ~* 'test is in this program|Ambient air in the high-care area' or d.sqf_reference like '%11.7%' then
    raise exception 'FSQM-015 still claims the ambient air test.';
  end if;
  if d.content::text ~* 'does not yet exist|once that log exists|RESULTS LOG DOES NOT EXIST' then
    raise exception 'FSQM-015 still says the results log does not exist.';
  end if;
  if (select count(*) from jsonb_array_elements_text(d.content->'procedure') l where l ~ '^◦ [1-4]-[A-F] ') <> 18 then
    raise exception 'FSQM-015 does not list the 18 sample points.';
  end if;
  if md5((d.content - 'purpose' - 'procedure' - 'form_references' - 'records' - 'governing_reference' - 'revision_history' - 'definitions')::text) <> '46ad3c966c474d46d3ac7352f928fab6' then
    raise exception 'a section of FSQM-015 that was not meant to change has changed.';
  end if;
  select status, type, content into f from public.sop_documents where sop_number = 'FRM-706';
  if f.status <> 'draft' or f.type <> 'form' then raise exception 'FRM-706 was not created as a draft form.'; end if;
  if (select count(*) from jsonb_array_elements(f.content->'form_schema'->'sections') s, jsonb_array_elements(s->'fields') x) <> 15 then
    raise exception 'FRM-706 field count is wrong.';
  end if;
  -- every sample point the program lists can be chosen on the log, word for word
  if exists (select 1 from jsonb_array_elements_text(d.content->'procedure') l
              where l ~ '^◦ [1-4]-[A-F] '
                and not (f.content->'form_schema'->'sections'->1->'fields'->0->'columns'->0->'options') ? substr(l, 3)) then
    raise exception 'a sample point in FSQM-015 is not an option on FRM-706.';
  end if;
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-015', 'FRM-706')
              and content::text ~* 'Diana|Gabriela|Christina|GJM|Mercer|Pillsbury|Amazon|Sysco|Bahamas') then
    raise exception 'a D-16 document names a person, a supplier or a customer; controlled documents name positions.';
  end if;
end $verify$;

commit;
